using J=p::Json;using R=os::ProcessorReadCode;using S=n::ProcessorStateCode;
const std::string utc="2026-10-12T05:00:00Z",later="2026-10-12T05:00:01Z";
void need(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
syspane::model::Tick tick(std::uint64_t ns){return {"epoch:1",ns,"clock:1","scope:1"};}
os::LinuxProcessorCapture capture(std::uint64_t a=40,std::uint64_t ai=60,std::uint64_t b=150,std::uint64_t bi=50){return {R::success,0,100,{{0,-1,0,{0},{a,0,0,ai,0,0,0,0},{}},{2,1,0,{2},{b,0,0,bi,0,0,0,0},{}}}};}
n::ProcessorState owner(){return n::ProcessorState("epoch:1","clock:1","scope:1","linux:execution-ticks-v1");}
void commit(n::ProcessorState& state,const os::LinuxProcessorCapture& raw,std::uint64_t ns){need(state.commit(1,state.revision(),raw.counters(),tick(ns),tick(ns))==S::accepted,"source accepted");}
c::Policy policy(){c::Policy v;v.available=true;v.revision=7;v.disclosure[{"console","inspector"}]={"operational"};v.disclosure[{"console","accessibility"}]={"operational"};return v;}
p::TelemetryBinding binding(){return {{1,p::frame_limit,{{"telemetry","0.2.0"},{"snapshot","0.2.0"},{"observation","0.2.0"}},{"telemetry.snapshot","telemetry.measured-time","telemetry.processor"}},"C","epoch:1","producer:network","S","inspector","operational",7,p::TelemetryDirection::producer_to_consumer,"0.2.0","clock:1","scope:1"};}
std::string encoded(J doc,const std::string& record){J body{{"schema_version","0.2.0"},{"subscription_id","S"},{"producer_id","producer:network"},{"record_id",record},{"policy_revision","7"},{"clock_id","clock:1"},{"snapshot",doc}};return p::encode_telemetry({"snapshot","C","epoch:1",body.dump(),body},binding());}
const J& field(const J& doc,std::string_view entity,std::string_view name){for(const auto& row:doc["observations"])if(row["entity_id"].get_ref<const std::string&>()==entity&&row["field"].get_ref<const std::string&>()==name)return row;throw std::runtime_error("missing expected field");}
void values(){auto state=owner();state.demand(1);auto raw=capture();n::LinuxProcessorPublisher pub("epoch:1","clock:1","scope:1");commit(state,raw,100);auto first=pub.document(state,&raw,1,utc,utc);need(first["entities"].size()==4&&first["observations"].size()==12,"complete two CPUs plus summaries");for(const auto& row:first["observations"])need(row["value"].is_null()&&row["acquisition"]=="pending"&&row["error"]["code"]=="processor.first","first never successful zero");raw=capture(80,80,230,70);commit(state,raw,200);auto doc=pub.document(state,&raw,2,later,later);const auto& percent=field(doc,"processor:aggregate","linux.cpu.execution_percent");need(percent["value"]["data"]==75&&percent["sample_interval_ns"]=="100","fixed weighted percent/actual interval");need(field(doc,"processor:aggregate","linux.cpu.interval_busy_ticks")["value"]["data"]=="120"&&field(doc,"processor:aggregate","linux.cpu.interval_total_ticks")["value"]["data"]=="160","exact integer denominators");need(field(doc,"processor:logical:1","linux.cpu.interval_busy_ticks")["value"]["data"]=="40"&&field(doc,"processor:logical:2","linux.cpu.interval_total_ticks")["value"]["data"]=="100","per CPU and aggregate mapping");need(first["generation"]=="1"&&first["observations"][0]["value"].is_null(),"retained immutable document");(void)encoded(doc,"values");need(n::processor_requested(J{{"widgets",J::array({{{"bindings",J::array({{{"field","linux.cpu.execution_percent"}}})}}})}}),"validated CPU scene requests source");need(!n::processor_requested(J{{"widgets",J::array({{{"bindings",J::array({{{"field","network.receive_bytes"}}})}}})}}),"network scene does not request CPU");}
void states(){auto state=owner();state.demand(1);auto raw=capture(0,100,0,100);n::LinuxProcessorPublisher pub("epoch:1","clock:1","scope:1");commit(state,raw,100);pub.document(state,&raw,1,utc,utc);raw=capture(0,200,0,200);commit(state,raw,200);auto doc=pub.document(state,&raw,2,later,later);need(field(doc,"processor:aggregate","linux.cpu.execution_percent")["value"]["data"]==0&&field(doc,"processor:aggregate","linux.cpu.interval_total_ticks")["value"]["data"]=="200","valid zero positive denominator");raw=capture(100,200,100,200);commit(state,raw,300);doc=pub.document(state,&raw,3,later,later);need(field(doc,"processor:aggregate","linux.cpu.execution_percent")["value"]["data"]==100,"full execution");commit(state,raw,400);doc=pub.document(state,&raw,4,later,later);need(doc["observations"][0]["value"].is_null()&&doc["observations"][0]["error"]["code"]=="processor.no_progress","no progress distinct from zero");}
void failure(){auto state=owner();state.demand(1);auto raw=capture();n::LinuxProcessorPublisher pub("epoch:1","clock:1","scope:1");commit(state,raw,100);pub.document(state,&raw,1,utc,utc);raw=capture(80,80,230,70);commit(state,raw,200);auto prior=pub.document(state,&raw,2,utc,utc);need(state.commit(1,0,{R::failed,5},tick(300),tick(300))==S::source_failed,"actual source failure");auto failed=pub.document(state,&raw,3,utc,later);for(std::size_t i=0;i<failed["observations"].size();++i){const auto& a=prior["observations"][i];const auto& b=failed["observations"][i];for(const char* key:{"value","observed_at","measured_at","sample_interval_ns"})need(a[key]==b[key],"retained measurement unchanged");need(b["attempted_at"]==later&&b["acquisition"]=="failed"&&b["freshness"]=="stale","failure is stale");}(void)encoded(failed,"failed");state.commit(1,0,{R::denied,13},tick(400),tick(400));auto denied=pub.document(state,&raw,4,utc,later);need(denied["observations"][0]["acquisition"]=="denied"&&denied["observations"][0]["freshness"]=="stale","denied retained status");state.commit(1,0,{R::unsupported,2},tick(500),tick(500));auto unsupported=pub.document(state,&raw,5,utc,later);for(const auto& row:unsupported["observations"])need(row["value"].is_null()&&row["support"]=="unsupported"&&row["freshness"]=="not_applicable","unsupported never retained healthy");(void)encoded(unsupported,"unsupported");raw=capture(180,180,330,170);commit(state,raw,600);auto resumed=pub.document(state,&raw,6,later,later);need(resumed["observations"][0]["value"].is_null()&&resumed["observations"][0]["error"]["code"]=="processor.acquisition_gap","recovery rebase");auto disabled=pub.document(state,&raw,7,later,later,true);need(disabled["entities"].size()==2,"disabled no old logical inventory");for(const auto& row:disabled["observations"])need(row["value"].is_null()&&row["acquisition"]=="disabled"&&row["measured_at"].is_null(),"disabled no old values");}
void lifetimes(){auto state=owner();state.demand(1);auto raw=capture();n::LinuxProcessorPublisher pub("epoch:1","clock:1","scope:1");commit(state,raw,100);bool capacity=false;try{pub.document(state,&raw,1,utc,utc,false,32);}catch(const p::Error& e){capacity=std::string(e.what())=="processor.publication_capacity";}need(capacity,"capacity fails without partial mapping");auto doc=pub.document(state,&raw,1,utc,utc);need(doc["entities"][2]["id"]=="processor:logical:1"&&doc["entities"][3]["id"]=="processor:logical:2","capacity rollback does not consume identities");raw.rows.pop_back();commit(state,raw,200);auto removed=pub.document(state,&raw,2,later,later);need(removed["entities"].size()==3,"removed logical retired");raw=capture();commit(state,raw,300);auto reintroduced=pub.document(state,&raw,3,later,later);need(reintroduced["entities"][3]["id"]=="processor:logical:3","raw index reuse cannot resurrect wire ID");r::DataView view({true,"console",{"console"}},policy(),"inspector","operational",n::processor_metrics());auto attachment=view.attach_wire(binding(),0);need(attachment.code==r::DataCode::accepted,"wire attach");for(auto item:{std::make_pair(doc,1),std::make_pair(removed,2),std::make_pair(reintroduced,3)})need(view.receive(attachment.token,7,encoded(item.first,"lifetime:"+std::to_string(item.second)),static_cast<std::uint64_t>(item.second),tick(301)).code==r::DataCode::accepted,"typed retirement/reintroduction import");}
void merge(){auto state=owner();state.demand(1);auto raw=capture();n::LinuxProcessorPublisher pub("epoch:1","clock:1","scope:1");commit(state,raw,100);n::NetworkState network("epoch:1","clock:1","scope:1");network.demand(1);need(network.commit(1,0,{os::NetworkCode::success,0,{{9,9,6,os::NetworkCounters{100,200}}}},tick(90),tick(90))==n::NetworkStateCode::accepted,"network fixture");auto network_doc=n::network_document(*network.sample(),1,utc,utc,true);raw=capture(80,80,230,70);commit(state,raw,200);auto doc=n::host_document(network_doc,pub.document(state,&raw,2,later,later),2,"epoch:1",later);need(doc["entities"].size()==5&&doc["sources"].size()==2&&doc["observations"].size()==16,"complete source merge");need(field(doc,"network:interface:1","network.receive_bytes")["measured_at"]["nanoseconds"]=="90"&&field(doc,"network:interface:1","network.receive_bytes")["attempted_at"]==utc,"CPU callback cannot rewrite network attempt/measurement");need(field(doc,"processor:aggregate","linux.cpu.execution_percent")["measured_at"]["nanoseconds"]=="200","CPU owns its own stamp");for(const auto& row:doc["observations"])need(row["generation"]=="2","one publication generation");(void)encoded(doc,"merge");bool capacity=false;try{n::host_document(network_doc,{},3,"epoch:1",later,32);}catch(const p::Error&){capacity=true;}need(capacity,"bounded merge never truncates");}
void boundary(){auto state=owner();state.demand(1);auto raw=capture();n::LinuxProcessorPublisher pub("epoch:1","clock:1","scope:1");commit(state,raw,100);r::DataView view({true,"console",{"console"}},policy(),"inspector","operational",n::processor_metrics());const auto attachment=view.attach_wire(binding(),0);auto bytes=encoded(pub.document(state,&raw,1,utc,utc),"first");need(view.receive(attachment.token,7,bytes,1,tick(100)).code==r::DataCode::accepted,"pending typed import");raw=capture(80,80,230,70);commit(state,raw,200);bytes=encoded(pub.document(state,&raw,2,later,later),"second");need(view.receive(attachment.token,7,bytes,2,tick(200)).code==r::DataCode::accepted&&view.receive(attachment.token,7,bytes,3,tick(201)).code==r::DataCode::duplicate,"typed value/replay");auto denied=policy();denied.available=false;denied.revision=8;view.policy(denied,4);need(!view.status(4).payload_available&&!view.project(4,[](const auto&,const auto&){}),"policy erases authority to project");}
J hello(bool cpu=true,bool current=true){J docs=J::array();for(const char* name:{"telemetry","snapshot","observation"})docs.push_back({{"document",name},{"version",current?"0.2.0":"0.1.0"}});return {{"type","hello"},{"body",{{"wire_major",0},{"wire_minor",1},{"role","console"},{"producer_epoch","consumer"},{"max_frame_bytes",p::frame_limit},{"document_versions",docs},{"required_features",cpu?J::array({"telemetry.snapshot","telemetry.measured-time","telemetry.processor"}):J::array({"telemetry.snapshot","telemetry.measured-time"})},{"optional_features",J::array()}}}};}
void negotiation(){
    c::TelemetrySource source{"producer:network","inspector","operational"};source.document_version="0.2.0";source.clock_id="clock:1";source.clock_scope="scope:1";source.processor=true;
    c::Sessions sessions("epoch:1",0,policy(),source);sessions.open("C","principal",{true,"console",{"console"}},0);sessions.receive("C",hello().dump(),1);const auto welcome=sessions.pop("C",1);need(welcome&&p::decode(*welcome).body["optional_features"].get<std::set<std::string>>().count("telemetry.processor"),"CPU feature explicitly negotiated");
    source.processor=false;c::Sessions unadvertised("epoch:1",0,policy(),source);unadvertised.open("C","principal",{true,"console",{"console"}},0);unadvertised.receive("C",hello().dump(),1);need(unadvertised.closed("C")&&!unadvertised.close_reason("C").empty()&&!unadvertised.pop("C",1),"unadvertised required CPU closes without welcome");
    source.processor=true;c::Sessions wrong_version("epoch:1",0,policy(),source);wrong_version.open("C","principal",{true,"console",{"console"}},0);wrong_version.receive("C",hello(true,false).dump(),1);need(wrong_version.closed("C")&&!wrong_version.close_reason("C").empty()&&!wrong_version.pop("C",1),"CPU requires measured document version");
}
void demand(){n::DemandSource source{"processor","collection.processor",1000,2500,"sampling.resources_ms",{}};for(const auto& metric:n::processor_metrics())source.fields.push_back({metric.field,"operational"});n::DemandRequest request;request.channel="inspector";for(const auto& metric:n::processor_metrics())request.selections.push_back({metric.field,{}});n::DemandOwner scheduler({source},policy());const auto lease=scheduler.admit(request,{true,"console",{"console"}},0);need(lease.code==n::DemandCode::accepted,"authorized source demand");const auto first=scheduler.take(0);need(first.has_value(),"first actual scheduler job");auto state=owner();state.demand(first->plan_revision);auto raw=capture();need(state.commit(first->plan_revision,0,raw.counters(),tick(100),tick(100))==S::accepted,"plan basis");scheduler.complete(first->ticket,0);scheduler.renew(lease.lease,1,1000);const auto next=scheduler.take(1000);need(next&&next->ticket!=first->ticket&&next->plan_revision==first->plan_revision,"new job same continuous plan");state.demand(next->plan_revision);raw=capture(80,80,230,70);need(state.commit(next->plan_revision,0,raw.counters(),tick(200),tick(200))==S::accepted&&state.sample()->aggregate->percent()==75,"cadence jobs produce interval rather than perpetual pending");scheduler.complete(next->ticket,1000);scheduler.release(lease.lease,1001);scheduler.admit(request,{true,"console",{"console"}},1002);const auto replacement=scheduler.take(2000);need(replacement&&replacement->plan_revision>next->plan_revision,"replacement plan");state.demand(replacement->plan_revision);need(state.commit(replacement->plan_revision,0,raw.counters(),tick(300),tick(300))==S::accepted&&state.sample()->pending==n::ProcessorPending::demand_changed,"replacement rebase");auto denied=policy();denied.denied_capabilities.insert("collection.processor");n::DemandOwner blocked({source},denied);need(blocked.admit(request,{true,"console",{"console"}},0).code==n::DemandCode::denied&&!blocked.take(0),"policy cannot dispatch CPU");}
int main(int argc,char** argv){try{need(argc==2,"case required");const std::string name=argv[1];if(name=="VALUES")values();else if(name=="STATES")states();else if(name=="FAILURE")failure();else if(name=="LIFETIMES")lifetimes();else if(name=="MERGE")merge();else if(name=="BOUNDARY")boundary();else if(name=="NEGOTIATION")negotiation();else if(name=="DEMAND")demand();else throw std::runtime_error("unknown case");std::cout<<name<<": pass\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
